SET
  @IsActive_2f6fdf4b0b30 = 1
SET
  @SpeedRank_2f6fdf4b0b30 = 10
SET
  @CostRank_2f6fdf4b0b30 = 2
SET
  @InheritTypeModalities_2f6fdf4b0b30 = 1
SET
  @ModelConfiguration_2f6fdf4b0b30 = N'{
  "LLM": {
    "SupportsNativeToolCalling": true,
    "DefaultToNativeToolCalling": false,
    "NativeControlFlow": "implicit",
    "NativeToolResults": true
  }
}' IF NOT EXISTS (
    SELECT
      1
    FROM
      [${flyway:defaultSchema}].[AIModel]
    WHERE
      [ID] = @ID_2f6fdf4b0b30
  )
BEGIN
EXEC [${flyway:defaultSchema}].spCreateAIModel @ID = @ID_2f6fdf4b0b30,
  @Name = @Name_2f6fdf4b0b30,
  @Description = @Description_2f6fdf4b0b30,
