  @Name_01894364b967 = N'Predictive Studio Prediction Retention'
SET
  @Description_01894364b967 = N'The daily Predictive Studio prediction maintenance. First the binding backfill: every MJ: ML Model Scoring Bindings row with no ViewAuthorizationID (the pre-change bindings the PR 4 migration reshaped) gets the seeded "View Model Predictions" authorization, looked up by name; while that authorization is not loaded nothing changes and the next run retries. Then the retention sweep: for every binding with a RetentionDays, active or withdrawn, its Source = ''Model'' Feature Values with an EffectiveAsOf more than RetentionDays days before the run''s UTC day are deleted through the entity layer, 1,000 per batch (Record Changes records each). It never deletes a binding, model or pipeline. The per-binding counts go to the job run''s Details. No configuration.'
SET
  @DriverClass_01894364b967 = N'PredictiveStudioPredictionRetentionJobDriver'
SET
  @NotificationsAvailable_01894364b967 = 1 IF NOT EXISTS (
    SELECT
      1
    FROM
      [${flyway:defaultSchema}].[ScheduledJobType]
    WHERE
      [ID] = @ID_01894364b967
  )
BEGIN
EXEC [${flyway:defaultSchema}].spCreateScheduledJobType @ID = @ID_01894364b967,
  @Name = @Name_01894364b967,
  @Description = @Description_01894364b967,
  @DriverClass = @DriverClass_01894364b967,
  @DomainRunEntity = @DomainRunEntity_01894364b967,
  @DomainRunEntity_Clear = 1,
  @DomainRunEntityFKey = @DomainRunEntityFKey_01894364b967,
  @DomainRunEntityFKey_Clear = 1,
