  SELECT
    [ID] AS [ID],
    [QueryID] AS [QueryID],
    [Name] AS [Name],
    [Type] AS [Type],
    [IsRequired] AS [IsRequired],
    [DefaultValue] AS [DefaultValue],
    [Description] AS [Description],
    [SampleValue] AS [SampleValue],
    [ValidationFilters] AS [ValidationFilters],
    [DetectionMethod] AS [DetectionMethod],
    [AutoDetectConfidenceScore] AS [AutoDetectConfidenceScore],
    CONVERT(
      NVARCHAR(19),
      CAST(
        SWITCHOFFSET([__mj_CreatedAt], '+00:00') AS DATETIME2(7)
      ),
      126
    ) + '.' + RIGHT(
      '00' + CONVERT(
        NVARCHAR(3),
        DATEPART(
          millisecond,
          CAST(
            SWITCHOFFSET([__mj_CreatedAt], '+00:00') AS DATETIME2(7)
          )
        )
      ),
      3
    ) + 'Z' AS [__mj_CreatedAt],
    CONVERT(
      NVARCHAR(19),
      CAST(
        SWITCHOFFSET([__mj_UpdatedAt], '+00:00') AS DATETIME2(7)
      ),
      126
    ) + '.' + RIGHT(
      '00' + CONVERT(
        NVARCHAR(3),
        DATEPART(
          millisecond,
          CAST(
            SWITCHOFFSET([__mj_UpdatedAt], '+00:00') AS DATETIME2(7)
          )
        )
      ),
      3
    ) + 'Z' AS [__mj_UpdatedAt],
    [IsServerSet] AS [IsServerSet],
    [Query] AS [Query]
  FROM
    @ResultTable_mjb1
  FOR JSON
    PATH,
    WITHOUT_ARRAY_WRAPPER,
    INCLUDE_NULL_VALUES
);
EXEC [${flyway:defaultSchema}].spCreateRecordChange_Internal @EntityName = N'MJ: Query Parameters',
@EntityID = '3D08228D-8D64-46D3-AED9-AABD54BBBDBE',
@RecordID = @ID_mjb1,
@UserID = 'ECAFCCEC-6A37-EF11-86D4-000D3A4E707E',
@Type = 'Create',
@ChangesJSON = N'',
@ChangesDescription = N'Record Created',
@FullRecordJSON = @__mj_FullRecordJSON_mjb1,
@Status = 'Complete',
@Comments = NULL,
@SuppressReturn = 1;
END;

SELECT
  *
FROM
  @ResultTable_mjb1;;

