@ExtractionStatus_1adfee45806e NVARCHAR(20),
@ExtractionMessage_1adfee45806e NVARCHAR(MAX),
@DefinitionFingerprint_1adfee45806e NVARCHAR(100)
SET
  @ID_1adfee45806e = '1E49AD2D-D4E7-4AFB-8928-FBF3929705AD'
SET
  @Name_1adfee45806e = N'Predictive Studio: Published Models Without A Publish Record'
SET
  @CategoryID_1adfee45806e = (
    SELECT
      [ID]
    FROM
      [${flyway:defaultSchema}].[QueryCategory]
    WHERE
      LOWER([Name]) = LOWER(N'Predictive Studio')
  )
SET
  @UserQuestion_1adfee45806e = N'Which Published models have no publish record, so they were published outside the lifecycle gate?'
SET
  @Description_1adfee45806e = N'Every Published MJ: ML Models row with a Delivery and no applied publish, rollback or adopt record in MJ: ML Model Publish Records (D4-204). The Predictive Studio registry check archives each through the lifecycle gate (status-written-outside-gate) and rolls the pipeline back when it is left with no Published model.'
SET
  @SQL_1adfee45806e = N'-- Predictive Studio registry check, finding (a) (§5.7 R6, R7): a Published model with a Delivery and no applied
-- `publish` record (a publish, a rollback or an adoption, D4-204) was set Published outside the lifecycle gate. Pre-change models
-- (Delivery IS NULL) are the pre-change migration''s (D4-61) and are left out. SQL Server only (D-057).
SELECT m.ID AS ModelID, m.PipelineID
FROM [${flyway:defaultSchema}].MLModel m
WHERE m.Status = ''Published''
  AND m.Delivery IS NOT NULL
  AND NOT EXISTS (
    SELECT 1 FROM [${flyway:defaultSchema}].MLModelPublishRecord r
    WHERE r.ModelID = m.ID AND r.Kind = ''publish'' AND r.Purpose IN (''publish'', ''rollback'', ''adopt'')
  )
