  @Name_718578e9d077 = N'Predictive Studio: Publish Records Without A Status Change'
SET
  @CategoryID_718578e9d077 = (
    SELECT
      [ID]
    FROM
      [${flyway:defaultSchema}].[QueryCategory]
    WHERE
      LOWER([Name]) = LOWER(N'Predictive Studio')
  )
SET
  @UserQuestion_718578e9d077 = N'Which publish records no longer match their model''s status?'
SET
  @Description_718578e9d077 = N'The newest applied publish, rollback or adopt record (D4-204) of each model whose model is gone or is neither Published nor Archived: a model moved off Published outside the gate (Validated or KeepBaseline, which the registry check restores through the lifecycle gate) or a record that matches no status change (recorded only).'
SET
  @SQL_718578e9d077 = N'-- Predictive Studio registry check, findings (b) and (h) (§5.7 R6, R7): the newest applied `publish` record of a
-- model (a publish or a rollback) whose model is no longer Published nor Archived by the gate: its status was changed
-- outside the gate (Validated or KeepBaseline: restored, (b)), or the record matches no status change (the model is
-- gone, or Draft or Unevaluated: recorded only, (h)). An `adopt` record has no status change by design (D4-61).
-- SQL Server only (D-057).
SELECT r.ID AS PublishRecordID, r.ModelID, r.TrainingRunID, r.Purpose, m.Status AS ModelStatus, m.PipelineID
FROM [${flyway:defaultSchema}].MLModelPublishRecord r
LEFT JOIN [${flyway:defaultSchema}].MLModel m ON m.ID = r.ModelID
WHERE r.Kind = ''publish''
  AND r.Purpose IN (''publish'', ''rollback'', ''adopt'')
  AND (m.ID IS NULL OR m.Status NOT IN (''Published'', ''Archived''))
  AND (r.ModelID IS NULL OR r.RecordedAt = (
    SELECT MAX(r2.RecordedAt) FROM [${flyway:defaultSchema}].MLModelPublishRecord r2
    WHERE r2.ModelID = r.ModelID AND r2.Kind = ''publish'' AND r2.Purpose IN (''publish'', ''rollback'', ''adopt'')
  ))
'
SET
  @TechnicalDescription_718578e9d077 = N'MLModelPublishRecord r LEFT JOIN MLModel m: Kind = ''publish'', Purpose publish, rollback or adopt (D4-204), the model''s newest such record (or the model deleted), and the model missing or its Status not Published or Archived. Returns PublishRecordID, ModelID, TrainingRunID, Purpose, ModelStatus, PipelineID. SQL Server only (D-057).'
SET
  @Status_718578e9d077 = N'Approved'
SET
  @QualityRank_718578e9d077 = 9
SET
  @ExecutionCostRank_718578e9d077 = 2
