SET
  @ExtractedSQLHash_718578e9d077 = N'33b52ebb80e6dc03d7ac347ff577968d49573977e7e1db7f2603d0451315af3f'
SET
  @ExtractionStatus_718578e9d077 = N'OK' IF NOT EXISTS (
    SELECT
      1
    FROM
      [${flyway:defaultSchema}].[Query]
    WHERE
      [ID] = @ID_718578e9d077
  )
BEGIN
