SET
  @ID_7b1127a99c0b = '8A03475E-DAA3-4706-AEC9-AE9C01CD95A9'
SET
  @Name_7b1127a99c0b = N'Run ML Model Monitoring'
SET
  @OperationKey_7b1127a99c0b = N'PredictiveStudio.RunModelMonitoring'
SET
  @CategoryID_7b1127a99c0b = (
    SELECT
      [ID]
    FROM
      [${flyway:defaultSchema}].[RemoteOperationCategory]
    WHERE
      LOWER([Name]) = LOWER(N'Predictive Studio')
  )
SET
  @Description_7b1127a99c0b = N'Run one Published MJ: ML Models row''s monitoring now, for one period (periodStart, the first day of a period of its monitoring job''s grain) or the last complete one: the period''s predictions (its binding''s Champion Model Feature Values, or a shadow Predict of the period''s unit rows when no binding is Active) joined to realised outcomes once the label window has closed, the primary score and tracked metrics with 95% intervals, drift by monitor procedure M, the retrain triggers (a fired one starts a challenger through the automated publisher), the rollback check against the predecessor on the same rows, the live mirror''s divergence and parity. Writes or updates the period''s MJ: ML Monitoring Results row and returns it. Uses the spec of the model''s open monitoring job. Delegates to PredictiveStudioModelMonitoringJobDriver in @memberjunction/predictive-studio.'
SET
  @InputTypeName_7b1127a99c0b = N'PredictiveStudioRunModelMonitoringInput'
SET
  @InputTypeDefinition_7b1127a99c0b = N'/** Input for `PredictiveStudio.RunModelMonitoring`. */
export interface PredictiveStudioRunModelMonitoringInput {
    /** Id of the Published `MJ: ML Models` row to monitor; its open monitoring job''s spec is used. */
    modelId: string;
    /** First day (`YYYY-MM-DD`) of the period to monitor, of the job''s grain; omitted: the last complete period. */
    periodStart?: string;
}
'
SET
  @InputTypeIsArray_7b1127a99c0b = 0
SET
  @OutputTypeName_7b1127a99c0b = N'PredictiveStudioRunModelMonitoringOutput'
SET
  @OutputTypeDefinition_7b1127a99c0b = N'/** One monitored period of `PredictiveStudio.RunModelMonitoring`: its `MJ: ML Monitoring Results` row as written. */
export interface PredictiveStudioMonitoredPeriod {
    /** First day of the period (`YYYY-MM-DD`). */
    period: string;
    /** Id of the period''s `MJ: ML Monitoring Results` row (a re-run updates it). */
    monitoringResultId: string;
    /** `window-open` (outcomes not yet known), `evaluated`, `insufficient-rows` (fewer scored rows than the job''s minimum: recorded, not judged) or `failed`. */
    state: ''window-open'' | ''evaluated'' | ''insufficient-rows'' | ''failed'';
    /** Predictions joined to a realised outcome. */
    joinedRows: number;
    /** The primary score''s value and its 95% bounds; absent unless evaluated. */
    primaryValue?: number;
