SET
  @ScopeType_171692fab830 = N'Filter'
SET
  @ScopeFilter_171692fab830 = N'EdgeType IN (''Defines'', ''Describes'', ''Measures'', ''Implements'') AND SourceEntity = ''MJ: Graph Concepts'' AND TargetEntity <> ''MJ: Graph Concepts'''
SET
  @OnChangeEnabled_171692fab830 = 0
SET
  @ScheduleEnabled_171692fab830 = 0
SET
  @Timezone_171692fab830 = N'UTC'
SET
  @OnDemandEnabled_171692fab830 = 1
